FORMAL_EMAILS = [
dict(id='f-beschwerde', t='Beschwerde: Deutschkurs', te='Complaint: German course', story='S09 Eine Beschwerde schreiben',
 task='Sie haben vor zwei Wochen einen Deutschkurs gebucht. Leider gibt es mehrere Probleme. Schreiben Sie an die Sprachschule.',
 pts=['Grund für Ihr Schreiben', 'Welche Probleme gibt es?', 'Was erwarten Sie?', 'Wie soll die Schule reagieren?'],
 bet='Betreff: Beschwerde über Deutschkurs B1', bete='Subject: Complaint about German course B1',
 anr='Sehr geehrte Damen und Herren,', anre='Dear Sir or Madam,',
 body=[
 ('{{ich schreibe Ihnen, weil ich mit}} meinem Deutschkurs bei Ihrer Schule {{nicht zufrieden bin}}. Ich habe den B1-Kurs vor zwei Wochen gebucht und möchte mich über mehrere Probleme beschweren.',
  'I am writing because I am not satisfied with my German course at your school. I booked the B1 course two weeks ago and want to complain about several problems.'),
 ('{{Das erste Problem ist, dass}} der Unterricht jeden Tag 15 Minuten zu spät beginnt. Das ist sehr ärgerlich, weil ich danach zur Arbeit muss. {{Außerdem}} sind die Räume oft schmutzig, und es gibt nicht genug Stühle für alle Teilnehmer.',
  'The first problem is that the lesson starts 15 minutes late every day. That is very annoying because I have to go to work afterwards. Also, the rooms are often dirty and there are not enough chairs for all participants.'),
 ('{{Darüber hinaus}} entspricht der Kurs nicht dem Niveau B1, wie es in Ihrer Werbung steht. Die Übungen sind zu einfach, und wir lernen nur Grammatik, die ich schon kenne. {{Deshalb}} mache ich keine Fortschritte.',
  'Furthermore, the course does not match level B1 as stated in your advertisement. The exercises are too easy and we only learn grammar I already know. Therefore I am not making progress.'),
 ('{{Ich erwarte von Ihnen, dass}} Sie diese Probleme schnell lösen. Der Unterricht sollte pünktlich beginnen, und die Räume sollten sauber sein. Außerdem möchte ich in einen anderen Kurs wechseln, der wirklich dem B1-Niveau entspricht.',
  'I expect you to solve these problems quickly. Lessons should start on time and the rooms should be clean. I would also like to switch to another course that really matches level B1.'),
 ('{{Ich bitte Sie, mir bis zum 5. Dezember eine Lösung anzubieten.}} Wenn sich nichts ändert, möchte ich mein Geld zurück und den Kurs kündigen. {{Ich hoffe auf eine baldige Antwort.}}',
  'I ask you to offer me a solution by 5 December. If nothing changes, I want my money back and will cancel the course. I hope for a quick reply.')],
 gruss='Mit freundlichen Grüßen', gruse='Yours faithfully,', name='Max Mustermann'),

dict(id='f-ofen', t='Der Ofen funktioniert nicht (Vermieter)', te='The oven does not work (landlord)', story='S23 Der Ofen funktioniert nicht',
 task='In Ihrer Küche funktioniert der Ofen nicht mehr. Schreiben Sie an den Vermieter, Herrn Berger.',
 pts=['Was ist kaputt und seit wann?', 'Was haben Sie schon versucht?', 'Warum ist das ein Problem?', 'Was soll der Vermieter tun?'],
 bet='Betreff: Defekter Ofen in der Küche, Wohnung 5', bete='Subject: Broken oven in the kitchen, flat 5',
 anr='Sehr geehrter Herr Berger,', anre='Dear Mr Berger,',
 body=[
 ('{{leider muss ich Ihnen mitteilen, dass}} der Ofen in meiner Küche seit gestern Abend nicht mehr funktioniert. Er wird nicht mehr heiß, obwohl er eingeschaltet ist. Die Wohnung ist die Nummer 5 im zweiten Stock.',
  'Unfortunately I have to tell you that the oven in my kitchen has not worked since yesterday evening. It does not get hot any more although it is switched on. The flat is number 5 on the second floor.'),
 ('Ich habe schon versucht, den Fehler selbst zu finden. Zuerst habe ich geprüft, ob der Stecker richtig in der Steckdose steckt. {{Dann}} habe ich die Sicherung im Flur kontrolliert, aber sie ist in Ordnung.',
  'I have already tried to find the fault myself. First I checked whether the plug is properly in the socket. Then I checked the fuse in the hallway, but it is fine.'),
 ('{{Das ist ein großes Problem für mich, weil}} ich jeden Tag zu Hause koche und im Moment nur eine kleine Herdplatte habe. {{Außerdem}} kommt am Wochenende mein Besuch, und ich möchte etwas backen.',
  'That is a big problem for me because I cook at home every day and currently only have one small hotplate. Also, my guests are coming at the weekend and I want to bake something.'),
 ('{{Ich möchte Sie bitten, bald einen Techniker zu schicken.}} Ich bin morgen und übermorgen ab 17 Uhr zu Hause. {{Könnten Sie mir bitte mitteilen, wann der Techniker kommt?}}',
  'I would like to ask you to send a technician soon. I am at home tomorrow and the day after tomorrow from 5 pm. Could you please tell me when the technician is coming?'),
 ('{{Vielen Dank im Voraus für Ihre Hilfe.}} {{Für weitere Fragen stehe ich gerne zur Verfügung.}} Sie erreichen mich unter 0151 1234567.',
  'Thank you in advance for your help. I am happy to answer any questions. You can reach me at 0151 1234567.')],
 gruss='Mit freundlichen Grüßen', gruse='Yours sincerely,', name='Max Mustermann'),

dict(id='f-anfrage', t='Anfrage: Erste-Hilfe-Kurs', te='Inquiry: first-aid course', story='S16 Anfrage zum Erste-Hilfe-Kurs',
 task='Sie möchten an einem Erste-Hilfe-Kurs teilnehmen. Schreiben Sie an die Volkshochschule.',
 pts=['Grund für Ihr Schreiben', 'Termin und Dauer', 'Kosten und Anmeldung', 'Bitte um Antwort'],
 bet='Betreff: Anfrage zum Erste-Hilfe-Kurs', bete='Subject: Inquiry about the first-aid course',
 anr='Sehr geehrte Damen und Herren,', anre='Dear Sir or Madam,',
 body=[
 ('{{ich möchte mich über}} Ihren Erste-Hilfe-Kurs {{informieren}}. Ich habe Ihre Anzeige im Internet gefunden und {{interessiere mich sehr für}} den Kurs, weil ich ihn für meinen Führerschein brauche.',
  'I would like to find out about your first-aid course. I found your advert on the internet and I am very interested in the course because I need it for my driving licence.'),
 ('{{Könnten Sie mir bitte mitteilen,}} wann der nächste Kurs beginnt und wie lange er dauert? {{Mich würde auch interessieren,}} ob der Kurs am Wochenende stattfindet, weil ich unter der Woche arbeite.',
  'Could you please tell me when the next course starts and how long it lasts? I would also like to know whether the course takes place at the weekend, because I work during the week.'),
 ('{{Außerdem möchte ich gerne wissen,}} wie viel der Kurs kostet und wie ich mich anmelden kann. Muss ich Unterlagen mitbringen, zum Beispiel einen Ausweis oder ein Passfoto? Kann ich die Gebühr bar bezahlen oder per Überweisung?',
  'I would also like to know how much the course costs and how I can register. Do I have to bring documents, for example an ID or a passport photo? Can I pay the fee in cash or by bank transfer?'),
 ('{{Ich wäre Ihnen dankbar, wenn Sie mir bis nächste Woche antworten könnten,}} weil die Plätze begrenzt sind und ich mich schnell entscheiden muss.',
  'I would be grateful if you could answer me by next week, because places are limited and I have to decide quickly.'),
 ('{{Vielen Dank im Voraus für Ihre Informationen.}} {{Ich freue mich auf Ihre Antwort.}}', 'Thank you in advance for your information. I look forward to your reply.')],
 gruss='Mit freundlichen Grüßen', gruse='Yours faithfully,', name='Max Mustermann'),

dict(id='f-bewerbung', t='Bewerbung: Aushilfe im Café', te='Application: part-time café job', story='S19 Eine Bewerbung schreiben',
 task='Das Café „Sonnenschein“ sucht eine Aushilfe für den Service (15 Stunden pro Woche). Schreiben Sie eine Bewerbung.',
 pts=['Wo haben Sie die Anzeige gelesen?', 'Warum möchten Sie die Stelle?', 'Erfahrung und Stärken', 'Wann können Sie anfangen? Bitte um Gespräch'],
 bet='Betreff: Bewerbung als Aushilfe im Service', bete='Subject: Application as part-time service staff',
 anr='Sehr geehrte Damen und Herren,', anre='Dear Sir or Madam,',
 body=[
 ('{{mit großem Interesse habe ich Ihre Anzeige}} in der Zeitung „Kölner Anzeiger“ vom 25. November {{gelesen}}. {{Hiermit bewerbe ich mich um die Stelle als}} Aushilfe im Service in Ihrem Café.',
  'I read your advertisement in the newspaper “Kölner Anzeiger” of 25 November with great interest. I hereby apply for the position of part-time service staff in your café.'),
 ('Die Arbeit im Café gefällt mir, weil ich gern mit Menschen arbeite und zu Gästen immer freundlich bin. {{Außerdem}} suche ich eine Stelle neben meinem Deutschkurs, und die Arbeitszeiten passen gut zu meinem Alltag.',
  'I like working in a café because I enjoy working with people and I am always friendly to guests. I am also looking for a job alongside my German course, and the working hours fit my daily routine well.'),
 ('{{Ich habe zwei Jahre als}} Kellner in einem Restaurant {{gearbeitet}} und kenne den Service gut. {{Ich bin}} pünktlich, zuverlässig und teamfähig, und ich lerne schnell. Meine Deutschkenntnisse sind auf dem Niveau B1.',
  'I worked as a waiter in a restaurant for two years and know service work well. I am punctual, reliable and a team player, and I learn quickly. My German is at level B1.'),
 ('{{Ich kann ab dem}} 1. Januar {{anfangen}} und am Nachmittag sowie am Wochenende arbeiten. Mein Lebenslauf und meine Zeugnisse sind dieser E-Mail als Anlage beigefügt.',
  'I can start from 1 January and work in the afternoon and at weekends. My CV and certificates are attached to this email.'),
 ('{{Über eine Einladung zu einem Vorstellungsgespräch würde ich mich sehr freuen.}} {{Für weitere Fragen stehe ich gerne zur Verfügung.}}',
  'I would be very happy about an invitation to an interview. I am happy to answer any questions.')],
 gruss='Mit freundlichen Grüßen', gruse='Yours faithfully,', name='Max Mustermann'),

dict(id='f-kuendigung', t='Kündigung: Fitnessstudio', te='Cancellation: gym membership', story='Typ: Kündigung',
 task='Sie sind Mitglied im Fitnessstudio „FitPlus“. Sie ziehen um und möchten die Mitgliedschaft beenden. Schreiben Sie an das Studio.',
 pts=['Grund für Ihr Schreiben', 'Warum kündigen Sie?', 'Zu welchem Datum?', 'Bitte um Bestätigung'],
 bet='Betreff: Kündigung der Mitgliedschaft, Mitgliedsnummer 12345', bete='Subject: Cancellation of membership, member no. 12345',
 anr='Sehr geehrte Damen und Herren,', anre='Dear Sir or Madam,',
 body=[
 ('{{hiermit möchte ich}} meine Mitgliedschaft in Ihrem Fitnessstudio {{kündigen}}. Meine Mitgliedsnummer ist 12345, und ich trainiere seit zwei Jahren bei Ihnen.',
  'I hereby cancel my membership at your gym. My member number is 12345 and I have trained with you for two years.'),
 ('{{Der Grund dafür ist, dass}} ich Ende Januar beruflich nach Aachen umziehe. {{Leider}} habe ich dann keine Möglichkeit mehr, Ihr Studio zu besuchen. Das Training bei Ihnen hat mir immer gut gefallen, und ich war mit dem Service sehr zufrieden.',
  'The reason is that I am moving to Aachen for work at the end of January. Unfortunately I will then no longer be able to visit your gym. I always liked training with you and was very satisfied with the service.'),
 ('Ich bitte Sie, die Kündigung zum 31. Januar zu bearbeiten. Falls das nach Ihren Vertragsbedingungen nicht möglich ist, {{teilen Sie mir bitte mit,}} zu welchem Termin die Mitgliedschaft endet.',
  'I ask you to process the cancellation for 31 January. If this is not possible under your contract terms, please tell me on which date the membership ends.'),
 ('{{Bitte bestätigen Sie mir die Kündigung schriftlich.}} {{Außerdem bitte ich Sie,}} nach diesem Termin keine Beiträge mehr von meinem Konto abzubuchen. Meine Adresse ändert sich ab Februar; die neue Adresse schicke ich Ihnen gern.',
  'Please confirm the cancellation in writing. I also ask you not to debit any more fees from my account after this date. My address changes from February; I will gladly send you the new address.'),
 ('{{Vielen Dank für Ihre Hilfe.}} {{Ich hoffe auf eine baldige Antwort.}}', 'Thank you for your help. I hope for a quick reply.')],
 gruss='Mit freundlichen Grüßen', gruse='Yours faithfully,', name='Max Mustermann'),

dict(id='f-mantel', t='Den Mantel zurückschicken', te='Returning a coat', story='S12 Den Mantel zurückschicken',
 task='Sie haben online einen Mantel bestellt, aber er passt nicht. Schreiben Sie an den Online-Shop.',
 pts=['Was haben Sie bestellt?', 'Was ist das Problem?', 'Was möchten Sie?', 'Bitte um Antwort'],
 bet='Betreff: Rückgabe der Bestellung Nr. 48213', bete='Subject: Return of order no. 48213',
 anr='Sehr geehrte Damen und Herren,', anre='Dear Sir or Madam,',
 body=[
 ('{{ich habe am 3. März bei Ihnen}} einen schwarzen Wintermantel in Größe M {{bestellt}}. Das Paket ist gestern angekommen, und die Bestellnummer ist 48213.',
  'I ordered a black winter coat in size M from you on 3 March. The parcel arrived yesterday and the order number is 48213.'),
 ('{{Leider}} passt der Mantel nicht, weil er zu klein ist. Ich habe ihn nur einmal anprobiert und nicht getragen. Auch die Farbe sieht auf dem Foto auf Ihrer Internetseite anders aus als in Wirklichkeit; sie ist viel dunkler.',
  'Unfortunately the coat does not fit because it is too small. I only tried it on once and have not worn it. The colour also looks different in the photo on your website than in reality; it is much darker.'),
 ('{{Deshalb möchte ich}} die Bestellung {{widerrufen}} und den Mantel {{zurückschicken}}. Ich möchte keinen anderen Mantel, sondern mein Geld zurückbekommen.',
  'Therefore I would like to withdraw the order and send the coat back. I do not want a different coat but my money back.'),
 ('{{Bitte teilen Sie mir mit,}} wie ich den Mantel zurückschicken kann und ob ich ein Rücksendeetikett bekomme. {{Könnten Sie mir bitte außerdem sagen,}} wie lange es dauert, bis das Geld auf meinem Konto ist?',
  'Please tell me how I can send the coat back and whether I get a return label. Could you also tell me how long it takes until the money is in my account?'),
 ('{{Vielen Dank im Voraus für Ihre Hilfe.}} {{Ich freue mich auf Ihre Rückmeldung.}}', 'Thank you in advance for your help. I look forward to your response.')],
 gruss='Mit freundlichen Grüßen', gruse='Yours faithfully,', name='Max Mustermann'),

dict(id='f-termin', t='Termin absagen mit Gegenvorschlag', te='Cancelling an appointment with a new proposal', story='S27 Eine Absage mit Gegenvorschlag (formelle Version)',
 task='Sie haben einen Termin beim Ausländeramt, aber Sie sind krank. Schreiben Sie eine E-Mail und schlagen Sie einen neuen Termin vor.',
 pts=['Grund für Ihr Schreiben', 'Warum können Sie nicht kommen?', 'Vorschlag für einen neuen Termin', 'Bitte um Bestätigung'],
 bet='Betreff: Terminabsage und Bitte um neuen Termin am 10. Dezember', bete='Subject: Cancelling the appointment and asking for a new one',
 anr='Sehr geehrte Frau Weber,', anre='Dear Ms Weber,',
 body=[
 ('{{ich schreibe Ihnen wegen}} meines Termins am Dienstag, dem 8. Dezember, um 10 Uhr. {{Leider muss ich diesen Termin absagen.}}',
  'I am writing about my appointment on Tuesday, 8 December at 10 am. Unfortunately I have to cancel this appointment.'),
 ('{{Der Grund ist, dass}} ich seit drei Tagen starke Grippe habe und Fieber habe. Mein Arzt hat gesagt, dass ich mindestens eine Woche zu Hause bleiben muss. Eine ärztliche Bescheinigung schicke ich Ihnen gern zu.',
  'The reason is that I have had a bad flu with fever for three days. My doctor said I have to stay at home for at least a week. I will gladly send you a medical certificate.'),
 ('{{Ich möchte Sie bitten, den Termin zu verschieben.}} {{Ich schlage vor,}} dass wir uns am Donnerstag, dem 17. Dezember, am Vormittag treffen. Falls dieser Tag nicht möglich ist, kann ich auch am Freitag, dem 18. Dezember, kommen.',
  'I would like to ask you to postpone the appointment. I suggest that we meet on Thursday, 17 December in the morning. If that day is not possible, I can also come on Friday, 18 December.'),
 ('{{Bitte geben Sie mir bis Montag Bescheid,}} ob einer dieser Termine für Sie passt. Ich entschuldige mich für die Umstände, die ich Ihnen damit mache.',
  'Please let me know by Monday whether one of these dates suits you. I apologise for the inconvenience this causes you.'),
 ('{{Vielen Dank für Ihr Verständnis.}} {{Ich freue mich auf Ihre Antwort.}}', 'Thank you for your understanding. I look forward to your reply.')],
 gruss='Mit freundlichen Grüßen', gruse='Yours sincerely,', name='Max Mustermann'),
]

INFORMAL_EMAILS = [
dict(id='i-einladung', t='Einladung zum Geburtstag', te='Birthday invitation', story='S26 Eine Einladung zum Geburtstag',
 task='Sie feiern Ihren Geburtstag. Schreiben Sie an eine Freundin eine E-Mail.',
 pts=['Anlass der Einladung', 'Wann und wo?', 'Essen und Trinken', 'Bitte um Antwort'],
 bet='Betreff: Einladung zu meiner Geburtstagsfeier', bete='Subject: Invitation to my birthday party',
 anr='Liebe Anna,', anre='Dear Anna,',
 body=[
 ('{{wie geht es dir?}} Ich hoffe, es geht dir gut. Ich schreibe dir, weil ich am 12. Dezember 31 Jahre alt werde. {{Ich möchte dich herzlich zu meiner Geburtstagsfeier einladen.}}',
  'How are you? I hope you are well. I am writing because I will turn 31 on 12 December. I would like to invite you warmly to my birthday party.'),
 ('{{Die Feier findet am}} Samstag, den 12. Dezember, {{um}} 18 Uhr {{bei mir zu Hause statt}}. Ich wohne in der Hauptstraße 15 im zweiten Stock. Du kannst mit der Straßenbahn Linie 7 bis zur Haltestelle „Rathaus“ fahren; von dort sind es nur fünf Minuten zu Fuß.',
  'The party takes place on Saturday, 12 December at 6 pm at my place. I live at Hauptstraße 15 on the second floor. You can take tram line 7 to the stop “Rathaus”; from there it is only five minutes on foot.'),
 ('{{Es gibt}} Pizza, Salat und selbst gemachten Kuchen. Getränke habe ich auch genug, aber wenn du möchtest, kannst du etwas Kleines zum Essen mitbringen. Es kommen ungefähr zehn Freunde, und du kennst fast alle.',
  'There will be pizza, salad and homemade cake. I also have enough drinks, but if you like you can bring something small to eat. About ten friends are coming and you know almost all of them.'),
 ('{{Ich hoffe, dass du kommen kannst.}} {{Bitte gib mir bis zum 5. Dezember Bescheid,}} damit ich genug Essen kaufen kann. Wenn du schon früher kommen möchtest, kannst du mir gern beim Vorbereiten helfen.',
  'I hope you can come. Please let me know by 5 December so that I can buy enough food. If you want to come earlier, you can gladly help me prepare.'),
 ('{{Ich freue mich auf deine Antwort!}}', 'I look forward to your answer!')],
 gruss='Viele Grüße', gruse='Best wishes,', name='Manoj'),

dict(id='i-absage', t='Absage mit Gegenvorschlag', te='Declining with a counter-proposal', story='S27 Eine Absage mit Gegenvorschlag',
 task='Ihr Freund Jonas hat Sie am Freitag ins Kino eingeladen. Sie sind krank. Schreiben Sie eine E-Mail.',
 pts=['Danke für die Einladung', 'Warum können Sie nicht?', 'Gegenvorschlag', 'Wie geht es weiter?'],
 bet='Betreff: Kino am Freitag', bete='Subject: Cinema on Friday',
 anr='Lieber Jonas,', anre='Dear Jonas,',
 body=[
 ('{{vielen Dank für deine Einladung}} ins Kino am Freitag. Der Film klingt sehr interessant, und ich habe mich wirklich darauf gefreut. {{Leider muss ich dir absagen.}}',
  'Thank you for your invitation to the cinema on Friday. The film sounds very interesting and I was really looking forward to it. Unfortunately I have to cancel.'),
 ('{{Der Grund ist, dass}} ich seit gestern krank bin. Ich habe Fieber und Husten und muss im Bett bleiben. Der Arzt hat gesagt, dass ich mindestens bis Sonntag zu Hause bleiben soll. Ich möchte dich nicht anstecken.',
  'The reason is that I have been ill since yesterday. I have a fever and a cough and have to stay in bed. The doctor said I should stay at home until Sunday at least. I do not want to infect you.'),
 ('{{Wie wäre es, wenn wir}} den Kinoabend auf nächste Woche {{verschieben}}? {{Ich schlage vor,}} dass wir am Samstag, den 19. Dezember, gehen. Dann bin ich bestimmt wieder gesund. {{Hast du da Zeit?}}',
  'How about postponing the cinema evening to next week? I suggest that we go on Saturday, 19 December. I will certainly be well again then. Are you free then?'),
 ('Wenn dir der Samstag nicht passt, können wir auch am Sonntagnachmittag gehen. Danach könnten wir noch etwas essen. Ich lade dich dann ein, weil ich dich diesmal enttäuschen muss.',
  'If Saturday does not suit you, we can also go on Sunday afternoon. Afterwards we could eat something. I will treat you then, because I have to disappoint you this time.'),
 ('{{Es tut mir wirklich leid.}} {{Schreib mir bitte, was du denkst.}} Ich melde mich, sobald es mir besser geht.',
  'I am really sorry. Please write to me what you think. I will get in touch as soon as I feel better.')],
 gruss='Liebe Grüße', gruse='Love,', name='Mia'),

dict(id='i-antwort', t='Antwort an eine Freundin', te='Reply to a friend', story='S08 Antwort an eine Freundin',
 task='Ihre Freundin Lisa hat eine neue Wohnung gefunden und lädt Sie zur Einweihung ein. Schreiben Sie eine Antwort.',
 pts=['Reaktion auf die Neuigkeit', 'Zusage und Uhrzeit', 'Was bringen Sie mit?', 'Ihre Frage'],
 bet='Betreff: Deine Einladung', bete='Subject: Your invitation',
 anr='Liebe Lisa,', anre='Dear Lisa,',
 body=[
 ('{{vielen Dank für deine Einladung!}} {{Ich habe mich sehr gefreut, dass}} du endlich eine neue Wohnung gefunden hast. Du hast so lange gesucht, und jetzt hat es doch geklappt. Herzlichen Glückwunsch!',
  'Thank you for your invitation! I was very happy that you finally found a new flat. You searched for so long and now it worked out after all. Congratulations!'),
 ('{{Natürlich komme ich gern.}} {{Leider kann ich nicht schon um}} 18 Uhr {{kommen, denn ich muss bis}} 19 Uhr {{arbeiten}}. Deshalb komme ich erst gegen 20 Uhr. Ist das in Ordnung für dich?',
  'Of course I will gladly come. Unfortunately I cannot come at 6 pm, because I have to work until 7 pm. Therefore I will only come around 8 pm. Is that okay for you?'),
 ('{{Was soll ich mitbringen?}} Ich könnte einen Salat machen oder ein paar Getränke mitbringen. Vielleicht möchtest du auch eine kleine Pflanze für die neue Wohnung? Ich habe zu Hause einen schönen Ableger, den ich dir gern schenke.',
  'What should I bring? I could make a salad or bring some drinks. Maybe you would also like a small plant for the new flat? I have a nice cutting at home that I would gladly give you.'),
 ('{{Ich habe noch eine Frage:}} Wie komme ich am besten zu dir? Ich habe gelesen, dass die Straßenbahn dort nicht mehr fährt, wegen einer Baustelle. Kann ich mit dem Bus fahren, oder soll ich dich lieber anrufen, wenn ich da bin?',
  'I have one more question: what is the best way to get to you? I read that the tram no longer runs there because of a building site. Can I take the bus, or should I call you when I am there?')],
 gruss='Bis bald', gruse='See you soon,', name='Manoj'),

dict(id='i-entschuldigung', t='Entschuldigung: verpasster Termin', te='Apology: missed meeting', story='Typ: Entschuldigung',
 task='Sie hatten mit einer Freundin einen Termin in der Stadt, sind aber nicht gekommen. Schreiben Sie eine E-Mail.',
 pts=['Entschuldigung', 'Warum sind Sie nicht gekommen?', 'Wie machen Sie es wieder gut?', 'Neuer Vorschlag'],
 bet='Betreff: Entschuldigung', bete='Subject: Apology',
 anr='Liebe Sara,', anre='Dear Sara,',
 body=[
 ('{{es tut mir sehr leid, dass}} ich gestern nicht zu unserem Treffen gekommen bin. Du hast bestimmt lange auf mich gewartet, und {{ich möchte mich dafür entschuldigen}}.',
  'I am very sorry that I did not come to our meeting yesterday. You surely waited for me for a long time and I would like to apologise for that.'),
 ('{{Der Grund ist, dass}} mein Zug eine Stunde Verspätung hatte. Ich wollte dich anrufen, aber mein Handy hatte keinen Akku mehr. {{Leider konnte ich dir keine Nachricht schicken,}} weil ich im Zug auch keinen Empfang hatte.',
  'The reason is that my train was an hour late. I wanted to call you but my phone had no battery. Unfortunately I could not send you a message because I had no signal on the train either.'),
 ('Ich weiß, dass das für dich nicht schön war, denn du hast extra frei genommen. {{Ich verspreche dir, dass das nicht wieder passiert.}} Das nächste Mal fahre ich einen Zug früher und nehme eine Powerbank mit.',
  'I know that was not nice for you because you took time off especially. I promise you that it will not happen again. Next time I will take an earlier train and bring a power bank.'),
 ('{{Kann ich etwas tun, um das wieder gutzumachen?}} Ich lade dich zum Essen ein, wenn du Lust hast. {{Wie wäre es mit}} Samstag um 13 Uhr in dem italienischen Restaurant am Markt? Sag mir einfach, ob der Tag für dich passt.',
  'Can I do something to make up for it? I will invite you for a meal if you like. How about Saturday at 1 pm in the Italian restaurant at the market? Just tell me whether the day suits you.'),
 ('{{Ich hoffe, dass du mir verzeihen kannst.}}', 'I hope you can forgive me.')],
 gruss='Liebe Grüße', gruse='Love,', name='Manoj'),

dict(id='i-dank', t='Danke für die Hilfe beim Umzug', te='Thanks for help with the move', story='Typ: Dankschreiben',
 task='Ihre Freundin hat Ihnen beim Umzug geholfen. Schreiben Sie eine E-Mail und bedanken Sie sich.',
 pts=['Dank', 'Was hat sie gemacht?', 'Wie ist die neue Wohnung?', 'Gegeneinladung'],
 bet='Betreff: Vielen Dank für deine Hilfe', bete='Subject: Thank you for your help',
 anr='Liebe Sara,', anre='Dear Sara,',
 body=[
 ('{{ich möchte mich ganz herzlich bei dir bedanken.}} {{Ohne deine Hilfe wäre}} der Umzug am Samstag nicht so schnell {{gegangen}}. Ich bin immer noch ein bisschen müde, aber sehr glücklich.',
  'I would like to thank you very much. Without your help the move on Saturday would not have gone so fast. I am still a bit tired but very happy.'),
 ('Du hast den ganzen Tag Kisten getragen, Möbel aufgebaut und sogar das Auto organisiert. {{Das war wirklich sehr nett von dir,}} weil du selbst viel zu tun hattest. Die Waschmaschine hätte ich allein nie in den dritten Stock bekommen.',
  'You carried boxes all day, assembled furniture and even organised the car. That was really very kind of you because you had a lot to do yourself. I would never have got the washing machine to the third floor on my own.'),
 ('Die neue Wohnung gefällt mir sehr gut. Sie ist hell und ruhig, und die Nachbarn sind freundlich. Ich habe schon fast alles ausgepackt; nur die Bücher stehen noch in den Kisten. {{Du musst unbedingt bald vorbeikommen und sie sehen.}}',
  'I like the new flat very much. It is bright and quiet and the neighbours are friendly. I have already unpacked almost everything; only the books are still in boxes. You really must come by soon and see it.'),
 ('{{Als kleines Dankeschön möchte ich dich zum Essen einladen.}} {{Hast du am Freitag um 19 Uhr Zeit?}} Ich koche für dich, und du darfst dir das Essen aussuchen. Sag mir einfach, ob dir der Tag passt.',
  'As a small thank-you I would like to invite you for dinner. Are you free on Friday at 7 pm? I will cook for you and you can choose the food. Just tell me whether the day suits you.'),
 ('{{Ich freue mich, wenn wir uns bald sehen!}}', 'I will be glad if we see each other soon!')],
 gruss='Herzliche Grüße', gruse='Warm regards,', name='Manoj'),

dict(id='i-ausflug', t='Gemeinsam einen Ausflug planen', te='Planning a trip together', story='S11 Gemeinsam einen Ausflug planen',
 task='Sie möchten mit Freunden am Wochenende einen Ausflug machen. Schreiben Sie einen Vorschlag.',
 pts=['Ihre Idee', 'Wann und wie fahren wir?', 'Was machen wir dort?', 'Was soll jeder mitbringen?'],
 bet='Betreff: Ausflug am Wochenende?', bete='Subject: Trip at the weekend?',
 anr='Hallo ihr Lieben,', anre='Hello dear all,',
 body=[
 ('{{ich habe eine Idee für das Wochenende:}} Das Wetter soll am Samstag schön werden, und {{ich schlage vor,}} dass wir zusammen einen Ausflug an den Rursee machen. Wir waren schon lange nicht mehr alle zusammen unterwegs.',
  'I have an idea for the weekend: the weather is supposed to be nice on Saturday and I suggest that we go on a trip to the Rursee together. We have not been out all together for a long time.'),
 ('{{Wir könnten}} um 9 Uhr am Hauptbahnhof {{treffen}} und mit dem Zug nach Düren fahren. Von dort fährt ein Bus direkt zum See. Die Fahrt dauert insgesamt etwa eineinhalb Stunden, und mit dem Gruppenticket ist es auch ziemlich günstig.',
  'We could meet at 9 am at the main station and take the train to Düren. From there a bus goes directly to the lake. The journey takes about an hour and a half in total and with the group ticket it is also quite cheap.'),
 ('{{Was haltet ihr davon, wenn}} wir am See spazieren gehen und danach ein Picknick machen? Wer möchte, kann ein Boot mieten. Am Nachmittag können wir noch ein Eis essen. Gegen 18 Uhr fahren wir wieder zurück.',
  'What do you think about walking at the lake and then having a picnic? Whoever wants can rent a boat. In the afternoon we can have an ice cream. Around 6 pm we go back.'),
 ('{{Bitte bringt}} etwas zu essen und zu trinken {{mit}}, zum Beispiel Obst, Brot oder Saft. Ich bringe eine Decke und einen Ball mit. Vergesst bitte nicht, warme Jacken und gute Schuhe anzuziehen.',
  'Please bring something to eat and drink, for example fruit, bread or juice. I will bring a blanket and a ball. Please do not forget to wear warm jackets and good shoes.'),
 ('{{Schreibt mir bitte bis Donnerstag, ob ihr mitkommt.}} {{Ich freue mich schon auf einen schönen Tag mit euch!}}',
  'Please write to me by Thursday whether you are coming. I am already looking forward to a nice day with you!')],
 gruss='Viele Grüße', gruse='Best wishes,', name='Manoj'),

dict(id='i-ofen', t='Mein Ofen ist kaputt: Kuchen bei dir backen?', te='My oven is broken: bake a cake at yours?', story='S23 Der Ofen funktioniert nicht (informelle Version)',
 task='Ihr Ofen funktioniert nicht, aber Sie wollen für Freitag einen Kuchen backen. Schreiben Sie an eine Freundin und bitten Sie um Hilfe.',
 pts=['Was ist das Problem?', 'Warum ist es wichtig?', 'Ihre Bitte', 'Was bieten Sie an?'],
 bet='Betreff: Kleine Bitte', bete='Subject: A small favour',
 anr='Liebe Lisa,', anre='Dear Lisa,',
 body=[
 ('{{ich habe eine kleine Bitte an dich.}} {{Leider muss ich dir sagen, dass}} mein Ofen seit gestern Abend nicht mehr funktioniert. Er wird einfach nicht mehr heiß. Ich habe schon geprüft, ob der Stecker drin ist, aber das ist er.',
  'I have a small favour to ask. Unfortunately I have to tell you that my oven has not worked since last night. It just does not get hot any more. I have already checked whether the plug is in, but it is.'),
 ('{{Das ist ein großes Problem für mich, weil}} ich am Freitag für meine Kollegen einen Kuchen backen wollte. Wir feiern im Büro, dass mein Projekt fertig ist. Ich habe die Zutaten schon gekauft und möchte nichts wegwerfen.',
  'That is a big problem for me because I wanted to bake a cake for my colleagues on Friday. We are celebrating at the office that my project is finished. I have already bought the ingredients and do not want to throw anything away.'),
 ('{{Könnte ich vielleicht}} am Donnerstagabend {{bei dir backen?}} {{Ich würde nur etwa zwei Stunden brauchen.}} Natürlich nur, wenn es bei dir passt. Mein Vermieter schickt erst nächste Woche jemanden, der den Ofen repariert.',
  'Could I perhaps bake at your place on Thursday evening? I would only need about two hours. Of course only if it suits you. My landlord is only sending someone to repair the oven next week.'),
 ('{{Als Dankeschön}} bringe ich die Zutaten für eine zweite Backform mit, und {{dann backen wir zusammen}} einen Kuchen für uns. Du kannst die Hälfte behalten, und wir essen ein Stück zusammen mit einem Kaffee.',
  'As a thank-you I will bring the ingredients for a second baking tin, and then we bake a cake for ourselves together. You can keep half and we will eat a piece together with a coffee.'),
 ('{{Schreib mir bitte kurz, ob das geht.}} {{Vielen Dank im Voraus!}}', 'Please write me briefly whether that works. Thank you in advance!')],
 gruss='Liebe Grüße', gruse='Love,', name='Manoj'),
]
